def main():
    os.makedirs(OUT, exist_ok=True)
    total = 0
    written = 0
    trig = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
    for cid in IDS:
        rec = P[cid]
        obj = {"case_id": cid, "prediction_text": rec["prediction_text"],
               "basis": rec["basis"], "confidence": rec["confidence"],
               "trigger": rec["trigger"]}
        path = os.path.join(OUT, cid + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(obj, f, ensure_ascii=False, indent=1)
        # 逐件自验：精确打开、JSON 可解析、字段齐、case_id 与文件名一致
        with open(path, "r", encoding="utf-8") as f:
            back = json.load(f)
        assert back["case_id"] == cid, cid
        for k in ("case_id", "prediction_text", "basis", "confidence", "trigger"):
            assert k in back and back[k] not in (None, ""), (cid, k)
        for k in ("changed_main", "reserve_used", "disputed", "reason"):
            assert k in back["trigger"], (cid, k)
        assert isinstance(back["confidence"], (int, float)) and 0 <= back["confidence"] <= 1, cid
        total += os.path.getsize(path)
        written += 1
        for k in trig:
            if back["trigger"][k]:
                trig[k] += 1
    assert written == 20, written
    print("batch_cases=", len(IDS))
    print("written=", written)
    print("trigger_counts=", trig)
    print("total_bytes=", total)

if __name__ == "__main__":
    main()
